   112	    /// `$created` becomes what this call added, when it added any.
   113	    private func noteCreated(since before: Set<UInt32>, in document: ProjectDocument) {
   114	        let snapshot = document.editedProject.snapshot
   115	        let added = snapshot.clips.map(\.id).filter { !before.contains($0) }
   116	        if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
   117	    }
